import java.io.*;
import java.util.*;
import java.util.regex.*;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";

        TreeMap<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        TreeSet<String> uniqueErrorMessages = new TreeSet<>();
        int[] hourCounts = new int[24];

        Pattern pattern = Pattern.compile("\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] (\\S+) \\(([^)]+)\\) - (.*)");

        try (BufferedReader br = Files.newBufferedReader(Paths.get(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                Matcher m = pattern.matcher(line);
                if (m.find()) {
                    String hourStr = m.group(1);
                    String level = m.group(2);
                    String component = m.group(3);
                    String message = m.group(4);

                    // Count entries by level
                    levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                    // Count entries by hour
                    int hour = Integer.parseInt(hourStr);
                    hourCounts[hour]++;

                    // Process errors
                    if ("ERROR".equals(level)) {
                        componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                        uniqueErrorMessages.add(message);
                    }
                }
            }
        } catch (IOException e) {
            // Silent catch for file errors as per requirements
        }

        // Find component with most errors
        String maxComp = "None";
        int maxErrCount = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > maxErrCount) {
                maxErrCount = entry.getValue();
                maxComp = entry.getKey();
            }
        }

        // Find busiest hour
        int maxHour = 0;
        int maxHourCount = -1;
        for (int i = 0; i < 24; i++) {
            if (hourCounts[i] > maxHourCount) {
                maxHourCount = hourCounts[i];
                maxHour = i;
            }
        }

        // Output results
        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();
        System.out.println("Component with Most Errors: " + maxComp + " (" + maxErrCount + " errors)");
        System.out.println();
        System.out.println("Unique Error Messages:");
        for (String msg : uniqueErrorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();
        System.out.println("Busiest Hour: " + String.format("%02d:00", maxHour) + " (" + maxHourCount + " entries)");
    }
}

