const FILE_PATH = '/tmp/…/employees.csv';

/**
 * Formats a number as USD currency with specified decimal places.
 */
function formatCurrency(value: number, decimals: number): string {
    return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
    }).format(value);
}

function main() {
    let rawData: string;
    try {
        rawData = fs.readFileSync(FILE_PATH, 'utf8');
    } catch (err) {
        return;
    }

    const lines = rawData.split(/\r?\n/).filter(line => line.trim() !== '');
    if (lines.length === 0) return;

    const rows = lines.slice(1);
    const deptStats = new Map<string, { total: number, count: number }>();
    let highestPaid = { name: '', salary: -Infinity };
    let totalBudget = 0;

    rows.forEach(line => {
        const cols = line.split(',');
        if (cols.length < 4) return;

        const name = cols[1].trim();
        const dept = cols[2].trim();
        // Remove any currency symbols or commas before parsing
        const salary = parseFloat(cols[3].trim().replace(/[^0-9.-]+/g, ''));

        if (isNaN(salary)) return;

        const stats = deptStats.get(dept) || { total: 0, count: 0 };
        stats.total += salary;
        stats.count += 1;
        deptStats.set(dept, stats);

        if (salary > highestPaid.salary) {
            highestPaid = { name, salary };
        }
        totalBudget += salary;
    });

    const sortedDepts = Array.from(deptStats.keys()).sort();

    // Output construction
    process.stdout.write('=== Salary Report ===\n\n');

    process.stdout.write('Average Salary by Department:\n');
    sortedDepts.forEach(dept => {
        const stats = deptStats.get(dept)!;
        const avg = stats.total / stats.count;
        process.stdout.write(`  ${dept}: ${formatCurrency(avg, 2)}\n`);
    });

    process.stdout.write('\n');
    process.stdout.write(`Highest Paid: ${highestPaid.name} (${formatCurrency(highestPaid.salary, 0)})\n`);

    process.stdout.write('\n');
    process.stdout.write('Departments with >2 employees:\n');
    sortedDepts.forEach(dept => {
        const stats = deptStats.get(dept)!;
        if (stats.count > 2) {
            process.stdout.write(`  ${dept} (${stats.count} employees)\n`);
        }
    });

    process.stdout.write('\n');
    process.stdout.write(`Total Budget: ${formatCurrency(totalBudget, 0)}\n`);
}

