import Foundation

let filePath = "/tmp/…/employees.csv"

do {
    let content = try String(contentsOfFile: filePath, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

    if lines.count <= 1 {
        exit(0)
    }

    let dataLines = lines.dropFirst()

    var deptSalaries: [String: [Double]] = [:]
    var highestPaidName = ""
    var highestPaidSalary: Double = -1.0
    var totalBudget: Double = 0.0

    for line in dataLines {
        let columns = line.components(separatedBy: ",")
        if columns.count < 6 { continue }

        let name = columns[1].trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "\"", with: "")
        let dept = columns[2].trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "\"", with: "")
        let salaryStr = columns[3].trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "\"", with: "").replacingOccurrences(of: ",", with: "")

        if let salary = Double(salaryStr) {
            deptSalaries[dept, default: []].append(salary)
            totalBudget += salary

            if salary > highestPaidSalary {
                highestPaidSalary = salary
                highestPaidName = name
            }
        }
    }

    let formatter = NumberFormatter()
    formatter.locale = Locale(identifier: "en_US")
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.usesGroupingSeparator = true

    func formatValue(_ value: Double, decimals: Int) -> String {
        formatter.minimumFractionDigits = decimals
        formatter.maximumFractionDigits = decimals
        return formatter.string(from: NSNumber(value: value)) ?? ""
    }

    print("=== Salary Report ===\n")

    print("Average Salary by Department:")
    let sortedDepts = deptSalaries.keys.sorted()
    for dept in sortedDepts {
        let salaries = deptSalaries[dept]!
        let avg = salaries.reduce(0, +) / Double(salaries.count)
        print("  \(dept): $\(formatValue(avg, decimals: 2))")
    }

    print("\nHighest Paid: \(highestPaidName) ($\(formatValue(highestPaidSalary, decimals: 0)))")

    print("\nDepartments with >2 employees:")
    for dept in sortedDepts {
        let count = deptSalaries[dept]!.count
        if count > 2 {
            print("  \(dept) (\(count) employees)")
        }
    }

    print("\nTotal Budget: $\(formatValue(totalBudget, decimals: 0))")

} catch {
    // Exit silently on error
}

import Foundation

let filePath = "/tmp/…/app.log"

do {
    let content = try String(contentsOfFile: filePath, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines)

    var entriesByLevel: [String: Int] = [:]
    var componentErrors: [String: Int] = [:]
    var uniqueErrorMessages: Set<String> = []
    var hourCounts: [String: Int] = [:]

    for line in lines {
        let trimmedLine = line.trimmingCharacters(in: .whitespaces)
        if trimmedLine.isEmpty { continue }

        guard let closingBracketIndex = line.firstIndex(of: "]") else { continue }
        let timestampPart = line[..<closingBracketIndex]
        let remaining = line[line.index(after: closingBracketIndex)...].trimmingCharacters(in: .whitespaces)

        // Extract hour from timestamp [YYYY-MM-DD HH:MM:SS]
        let tsTrimmed = timestampPart.trimmingCharacters(in: CharacterSet(charactersIn: "["))
        let tsParts = tsTrimmed.split(separator: " ")
        if tsParts.count >= 2 {
            let time = String(tsParts[1])
            let hour = String(time.prefix(2))
            hourCounts[hour, default: 0] += 1
        }

        // Extract Level, Component, and Message from "LEVEL (component) - message"
        guard let openParenIndex = remaining.firstIndex(of: "(") else { continue }
        let level = remaining[..<openParenIndex].trimmingCharacters(in: .whitespaces)

        guard let closeParenIndex = remaining.firstIndex(of: ")") else { continue }
        let component = remaining[remaining.index(after: openParenIndex)..<closeParenIndex]

        guard let dashRange = remaining.range(of: " - ") else { continue }
        let message = remaining[dashRange.upperBound...]

        entriesByLevel[level, default: 0] += 1
        if level == "ERROR" {
            componentErrors[String(component), default: 0] += 1
            uniqueErrorMessages.insert(String(message))
        }
    }

    print("=== Log Analysis ===")
    print("")

    print("Entries by Level:")
    let sortedLevels = entriesByLevel.keys.sorted()
    for level in sortedLevels {
        print("  \(level): \(entriesByLevel[level]!)")
    }

    print("")
    let topComp = componentErrors.sorted { 
        $0.value == $1.value ? $0.key < $1.key : $0.value > $1.value 
    }.first
    print("Component with Most Errors: \(topComp?.key ?? "None") (\(topComp?.value ?? 0) errors)")

    print("")
    print("Unique Error Messages:")
    let sortedErrors = uniqueErrorMessages.sorted()
    for msg in sortedErrors {
        print("  - \(msg)")
    }

    print("")
    let topHour = hourCounts.sorted { 
        $0.value == $1.value ? $0.key < $1.key : $0.value > $1.value 
    }.first
    print("Busiest Hour: \(topHour?.key ?? "00"):00 (\(topHour?.value ?? 0) entries)")

} catch {
    // Silently fail or handle as needed; prompt requires runnable code
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[128];
    double total_salary;
    int count;
} DeptInfo;

void format_number(double num, char *out, int precision) {
    char temp[64];
    sprintf(temp, "%.*f", precision, num);
    char *dot = strchr(temp, '.');
    int int_len = dot ? (int)(dot - temp) : (int)strlen(temp);
    int j = 0;
    for (int i = 0; i < int_len; i++) {
        if (i > 0 && (int_len - i) % 3 == 0) {
            out[j++] = ',';
        }
        out[j++] = temp[i];
    }
    if (dot) {
        strcpy(&out[j], dot);
    } else {
        out[j] = '\0';
    }
}

int compare_depts(const void *a, const void *b) {
    return strcmp(((DeptInfo *)a)->name, ((DeptInfo *)b)->name);
}

void parse_line(char *line, char *fields[]) {
    int i = 0;
    char *ptr = line;
    fields[i++] = ptr;
    while (*ptr) {
        if (*ptr == ',') {
            *ptr = '\0';
            ptr++;
            fields[i++] = ptr;
        } else if (*ptr == '\n' || *ptr == '\r') {
            *ptr = '\0';
            break;
        } else {
            ptr++;
        }
    }
}

int main(void) {
    const char *filepath = "/tmp/…/employees.csv";
    FILE *fp = fopen(filepath, "r");
    if (!fp) return 0;

    char *line = malloc(4096);
    char *fields[10];

    if (!fgets(line, 4096, fp)) {
        free(line);
        fclose(fp);
        return 0;
    }

    DeptInfo *depts = malloc(1000 * sizeof(DeptInfo));
    int dept_count = 0;
    double total_budget = 0;
    double highest_salary = -1.0;
    char highest_paid_name[128] = "";

    while (fgets(line, 4096, fp)) {
        parse_line(line, fields);
        if (fields[1] == NULL || fields[2] == NULL || fields[3] == NULL) continue;

        char *name = fields[1];
        char *dept_name = fields[2];
        double salary = atof(fields[3]);

        total_budget += salary;
        if (salary > highest_salary) {
            highest_salary = salary;
            strncpy(highest_paid_name, name, sizeof(highest_paid_name) - 1);
        }

        int found = 0;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].name, dept_name) == 0) {
                depts[i].total_salary += salary;
                depts[i].count++;
                found = 1;
                break;
            }
        }
        if (!found && dept_count < 1000) {
            strncpy(depts[dept_count].name, dept_name, sizeof(depts[dept_count].name) - 1);
            depts[dept_count].total_salary = salary;
            depts[dept_count].count = 1;
            dept_count++;
        }
    }

    qsort(depts, dept_count, sizeof(DeptInfo), compare_depts);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_count; i++) {
        char buf[64];
        format_number(depts[i].total_salary / depts[i].count, buf, 2);
        printf("  %s: $%s\n", depts[i].name, buf);
    }

    printf("\n");
    char high_sal_buf[64];
    format_number(highest_salary, high_sal_buf, 0);
    printf("Highest Paid: %s ($%s)\n", highest_paid_name, high_sal_buf);

    printf("\nDepartments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }

    printf("\n");
    char budget_buf[64];
    format_number(total_budget, budget_buf, 0);
    printf("Total Budget: $%s\n", budget_buf);

    free(line);
    free(depts);
    fclose(fp);
    return 0;
}

import * as fs from 'fs';

const filePath = '/tmp/…/app.log';

function analyzeLogs() {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split(/\r?\n/);

        const levelCounts = new Map<string, number>();
        const componentErrorCounts = new Map<string, number>();
        const uniqueErrorMessages = new Set<string>();
        const hourCounts = new Map<string, number>();

        const logLineRegex = /^\[\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\] (\S+) \(([^)]+)\) - (.*)$/;

        for (const line of lines) {
            if (!line.trim()) continue;

            const match = line.match(logLineRegex);
            if (match) {
                const [_, hour, level, component, message] = match;

                // Count all entries by level
                levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

                // Count all entries by hour
                hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);

                // Only track errors for components and unique messages
                if (level === 'ERROR') {
                    componentErrorCounts.set(component, (componentErrorCounts.get(component) || 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }
        }

        process.stdout.write('=== Log Analysis ===\n\n');

        process.stdout.write('Entries by Level:\n');
        const sortedLevels = Array.from(levelCounts.keys()).sort();
        for (const level of sortedLevels) {
            process.stdout.write(`  ${level}: ${levelCounts.get(level)}\n`);
        }
        process.stdout.write('\n');

        let maxComp = '';
        let maxErrCount = 0;
        for (const [comp, count] of componentErrorCounts.entries()) {
            if (count > maxErrCount) {
                maxErrCount = count;
                maxComp = comp;
            }
        }
        process.stdout.write(`Component with Most Errors: ${maxComp} (${maxErrCount} errors)\n\n`);

        process.stdout.write('Unique Error Messages:\n');
        const sortedErrors = Array.from(uniqueErrorMessages).sort();
        for (const err of sortedErrors) {
            process.stdout.write(`  - ${err}\n`);
        }
        process.stdout.write('\n');

        let maxHour = '';
        let maxHourCount = 0;
        for (const [hour, count] of hourCounts.entries()) {
            if (count > maxHourCount) {
                maxHourCount = count;
                maxHour = hour;
            }
        }
        process.stdout.write(`Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)\n`);

    } catch (error) {
        // Silently handle file not found or read errors
    }
}

analyzeLogs();

