        JsonParser parserA = new JsonParser(contentA);
        JsonParser parserB = new JsonParser(contentB);

        Object objA = parserA.parse();
        Object objB = parserB.parse();

        Object merged = merge(objA, objB);

        JsonSerializer serializer = new JsonSerializer();
        System.out.println(serializer.serialize(merged, 0));
    }

    static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;
            Map<String, Object> result = new TreeMap<>();
            result.putAll(mapA);
            for (Map.Entry<String, Object> entry : mapB.entrySet()) {
                String key = entry.getKey();
                Object valB = entry.getValue();
                if (result.containsKey(key)) {
                    result.put(key, merge(result.get(key), valB));
                } else {
                    result.put(key, valB);
                }
            }
            return result;
        } else if (a instanceof List && b instanceof List) {
            List<Object> listA = (List<Object>) a;
            List<Object> listB = (List<Object>) b;
            List<Object> result = new ArrayList<>(listA);
            for (Object itemB : listB) {
                if (!result.contains(itemB)) {
                    result.add(itemB);
                }
            }
            return result;
        } else {
            return b;
        }
    }

    static class JsonParser {
        private final String input;
        private int pos = 0;

        public JsonParser(String input) {
            this.input = input;
        }

        public Object parse() {
            return parseValue();
        }

        private Object parseValue() {
            skipWhitespace();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') return parseNull();
            return parseNumber();
        }

        private Map<String, Object> parseObject() {
            pos++; // skip {
            Map<String, Object> map = new TreeMap<>();
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ':') pos++;
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == '}') {
                    pos++;
                    break;
                }
                if (pos < input.length() && input.charAt(pos) == ',') pos++;
            }
            return map;
        }

        private List<Object> parseArray() {
            pos++; // skip [
            List<Object> list = new ArrayList<>();
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                list.add(parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                if (pos < input.length() && input.charAt(pos) == ',') pos++;
                skipWhitespace();
            }
            return list;
        }

        private String parseString() {
            pos++; // skip "
            StringBuilder sb = new StringBuilder();
            while (pos < input.length() && input.charAt(pos) != '"') {
                char c = input.charAt(pos++);
                if (c == '\\') {
                    if (pos < input.length()) {
                        char next = input.charAt(pos++);
                        switch (next) {
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            default: sb.append(next); break;
                        }
                    }
                } else {
                    sb.append(c);
                }
            }
            pos++; // skip "
            return sb.toString();
        }

        private Boolean parseBoolean() {
            if (input.startsWith("true", pos)) {
                pos += 4;
                return true;
            } else {
                pos += 5;
                return false;
            }
        }

        private Object parseNull() {
            pos += 4;
            return null;
        }

        private Object parseNumber() {
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (Character.isDigit(c) || ".-eE+".indexOf(c) != -1) {
                    sb.append(c);
                    pos++;
                } else {
                    break;
                }
            }
            String s = sb.toString();
            try {
                if (s.contains(".") || s.contains("e") || s.contains("E")) {
                    return Double.parseDouble(s);
                } else {
                    return Long.parseLong(s);
                }
            } catch (NumberFormatException e) {
                return Double.parseDouble(s);
            }
        }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) {
                pos++;
            }
        }
    }

    static class JsonSerializer {
        public String serialize(Object obj, int indentLevel) {
            if (obj == null) return "null";
            if (obj instanceof String) return "\"" + escapeString((String) obj) + "\"";
            if (obj instanceof Number || obj instanceof Boolean) return obj.toString();
            if (obj instanceof List) {
                List<Object> list = (List<Object>) obj;
                if (list.isEmpty()) return "[]";
                StringBuilder sb = new StringBuilder("[\n");
                String nextIndent = " ".repeat((indentLevel + 1) * 2);
                for (int i = 0; i < list.size(); i++) {
                    sb.append(nextIndent).append(serialize(list.get(i), indentLevel + 1));
                    if (i < list.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append(" ".repeat(indentLevel * 2)).append("]");
                return sb.toString();
            }
            if (obj instanceof Map) {
                Map<String, Object> map = (Map<String, Object>) obj;
                if (map.isEmpty()) return "{}";
                StringBuilder sb = new StringBuilder("{\n");
                String nextIndent = " ".repeat((indentLevel + 1) * 2);
                List<String> sortedKeys = new ArrayList<>(map.keySet());
                Collections.sort(sortedKeys);
                for (int i = 0; i < sortedKeys.size(); i++) {
                    String key = sortedKeys.get(i);
                    sb.append(nextIndent).append("\"").append(key).append("\": ").append(serialize(map.get(key), indentLevel + 1));
                    if (i < sortedKeys.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append(" ".repeat(indentLevel * 2)).append("}");
                return sb.toString();
            }
            return "";
        }

        private String escapeString(String s) {
            StringBuilder sb = new StringBuilder();
            for (char c : s.toCharArray()) {
                switch (c) {
                    case '"': sb.append("\\\""); break;
                    case '\\': sb.append("\\\\"); break;
                    case '\b': sb.append("\\b"); break;
                    case '\f': sb.append("\\f"); break;
                    case '\n': sb.append("\\n"); break;
                    case '\r': sb.append("\\r"); break;
                    case '\t': sb.append("\\t"); break;
                    default: sb.append(c); break;
                }
            }
            return sb.toString();
        }
    }
}

