import Foundation

struct Edge: Codable {
    let from: String
    let to: String
    let weight: Int
}

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

func solve() {
    let filePath = "/tmp/…/graph.json"

    guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
        return
    }

    let decoder = JSONDecoder()
    guard let graphData = try? decoder.decode(GraphData.self, from: data) else {
        return
    }

    let nodes = graphData.nodes
    var adj = [String: [(node: String, weight: Int)]]()

    for node in nodes {
        adj[node] = []
    }

    for edge in graphData.edges {
        adj[edge.from]?.append((edge.to, edge.weight))
        adj[edge.to]?.append((edge.from, edge.weight))
    }

    var distances = [String: Int]()
    for node in nodes {
        distances[node] = Int.max
    }

    let startNode = "A"
    distances[startNode] = 0

    var visited = Set<String>()

    while visited.count < nodes.count {
        var minNode: String? = nil
        var minDistance = Int.max

        for node in nodes {
            if !visited.contains(node) {
                let dist = distances[node] ?? Int.max
                if dist < minDistance {
                    minDistance = dist
                    minNode = node
                }
            }
        }

        guard let u = minNode else {
            break
        }

        visited.insert(u)

        if let uDist = distances[u], uDist != Int.max {
            if let neighbors = adj[u] {
                for (v, weight) in neighbors {
                    if !visited.contains(v) {
                        let alt = uDist + weight
                        if alt < (distances[v] ?? Int.max) {
                            distances[v] = alt
                        }
                    }
                }
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print("")

    let sortedNodes = nodes.sorted()
    for node in sortedNodes {
        let dist = distances[node] ?? Int.max
        print("A -> \(node): \(dist)")
    }
}

