import java.io.*;
import java.net.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://127.0.0.1:18924/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                response.append(line);
            }
            in.close();

            String json = response.toString();
            List<Product> products = new ArrayList<>();

            Pattern objectPattern = Pattern.compile("\\{(.*?)\\}");
            Matcher objectMatcher = objectPattern.matcher(json);

            while (objectMatcher.find()) {
                String objectContent = objectMatcher.group(1);

                Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]*)\"");
                Matcher nameMatcher = namePattern.matcher(objectContent);
                String name = "";
                if (nameMatcher.find()) {
                    name = nameMatcher.group(1);
                }

                Pattern pricePattern = Pattern.compile("\"price\"\\s*:\\s*([-+]?[0-9]*\\.?[0-9]+)");
                Matcher priceMatcher = pricePattern.matcher(objectContent);
                double price = 0.0;
                if (priceMatcher.find()) {
                    price = Double.parseDouble(priceMatcher.group(1));
                }
                products.add(new Product(name, price));
            }

            List<Product> filtered = new ArrayList<>();
            for (Product p : products) {
                if (p.price > 50.00) {
                    filtered.add(p);
                }
            }

            Collections.sort(filtered, new Comparator<Product>() {
                @Override
                public int compare(Product p1, Product p2) {
                    return p1.name.compareTo(p2.name);
                }
            });

            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();
            double total = 0;
            for (Product p : filtered) {
                System.out.printf("%s: $%.2f%n", p.name, p.price);
                total += p.price;
            }
            System.out.println();
            System.out.println("Count: " + filtered.size());
            System.out.printf("Total: $%.2f%n", total);

        } catch (Exception e) {
            // Silent catch as per requirements to output only specified format
        }
    }
}

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut level_counts = BTreeMap::new();
    let mut component_errors = HashMap::new();
    let mut error_messages = BTreeSet::new();
    let mut hour_counts = [0usize; 24];

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.is_empty() {
            continue;
        }

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = match line.find(']') {
            Some(idx) => idx,
            None => continue,
        };

        let timestamp = &line[1..bracket_end];
        if timestamp.len() >= 13 {
            let hour_str = &timestamp[11..13];
            if let Ok(hour) = hour_str.parse::<usize>() {
                if hour < 24 {
                    hour_counts[hour] += 1;
                }
            }
        }

        let rest = if line.len() > bracket_end + 2 {
            &line[bracket_end + 2..]
        } else {
            ""
        };

        let paren_start = match rest.find('(') {
            Some(idx) => idx,
            None => continue,
        };

        let level = rest[..paren_start].trim();
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let paren_end = match rest.find(')') {
            Some(idx) => idx,
            None => continue,
        };

        let component = &rest[paren_start + 1..paren_end];

        let message = if rest.len() > paren_end + 4 {
            &rest[paren_end + 4..]
        } else {
            ""
        };

        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===\n");
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }

    let mut max_errors = 0;
    let mut most_err_comp = String::new();
    for (comp, count) in &component_errors {
        if *count > max_errors {
            max_errors = *count;
            most_err_comp = comp.clone();
        }
    }
    println!("\nComponent with Most Errors: {} ({} errors)", most_err_comp, max_errors);

    println!("\nUnique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }

    let mut max_hour_count = 0;
    let mut busiest_hour = 0;
    for (hour, count) in hour_counts.iter().enumerate() {
        if *count > max_hour_count {
            max_hour_count = *count;
            busiest_hour = hour;
        }
    }
    println!("\nBusiest Hour: {:02}:00 ({} entries)", busiest_hour, max_hour_count);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JsonType;

typedef struct JsonValue JsonValue;

typedef struct {
    char *key;
    JsonValue *val;
} JsonEntry;

struct JsonValue {
    JsonType type;
    union {
        bool b;
        double n;
        char *s;
        struct {
            JsonEntry *entries;
            int count;
            int capacity;
        } obj;
        struct {
            JsonValue **elements;
            int count;
            int capacity;
        } arr;
    };
};

char *my_strdup(const char *s) {
    size_t len = strlen(s);
    char *d = malloc(len + 1);
    if (d) strcpy(d, s);
    return d;
}

JsonValue *create_value(JsonType type) {
    JsonValue *v = calloc(1, sizeof(JsonValue));
    v->type = type;
    return v;
}

void free_json_value(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_STRING) {
        free(v->s);
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->arr.count; i++) free_json_value(v->arr.elements[i]);
        free(v->arr.elements);
    } else if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->obj.count; i++) {
            free(v->obj.entries[i].key);
            free_json_value(v->obj.entries[i].val);
        }
        free(v->obj.entries);
    }
    free(v);
}

JsonValue *copy_value(JsonValue *v) {
    if (!v) return NULL;
    JsonValue *res = create_value(v->type);
    if (v->type == JSON_STRING) {
        res->s = my_strdup(v->s);
    } else if (v->type == JSON_BOOL) {
        res->b = v->b;
    } else if (v->type == JSON_NUMBER) {
        res->n = v->n;
    } else if (v->type == JSON_ARRAY) {
        res->arr.count = v->arr.count;
        res->arr.capacity = v->arr.count > 0 ? v->arr.count : 4;
        res->arr.elements = malloc(sizeof(JsonValue *) * res->arr.capacity);
        for (int i = 0; i < v->arr.count; i++) res->arr.elements[i] = copy_value(v->arr.elements[i]);
    } else if (v->type == JSON_OBJECT) {
        res->obj.count = v->obj.count;
        res->obj.capacity = v->obj.count > 0 ? v->obj.count : 4;
        res->obj.entries = malloc(sizeof(JsonEntry) * res->obj.capacity);
        for (int i = 0; i < v->obj.count; i++) {
            res->obj.entries[i].key = my_strdup(v->obj.entries[i].key);
            res->obj.entries[i].val = copy_value(v->obj.entries[i].val);
        }
    }
    return res;
}

const char *skip_ws(const char *p) {
    while (*p && isspace(*p)) p++;
    return p;
}

char *parse_json_string(const char **p) {
    (*p)++;
    const char *start = *p;
    while (**p && **p != '\"') {
        if (**p == '\\') (*p)++;
        (*p)++;
    }
    size_t len = *p - start;
    char *s = malloc(len + 1);
    memcpy(s, start, len);
    s[len] = '\0';
    if (**p == '\"') (*p)++;
    return s;
}

JsonValue *parse_json_value(const char **p);

JsonValue *parse_json_object(const char **p) {
    JsonValue *v = create_value(JSON_OBJECT);
    v->obj.capacity = 4;
    v->obj.entries = malloc(sizeof(JsonEntry) * v->obj.capacity);
    v->obj.count = 0;
    (*p)++;
    while (true) {
        *p = skip_ws(*p);
        if (**p == '}') {
            (*p)++;
            break;
        }
        char *key = parse_json_string(p);
        *p = skip_ws(*p);
        if (**p == ':') (*p)++;
        *p = skip_ws(*p);
        JsonValue *val = parse_json_value(p);
        if (v->obj.count >= v->obj.capacity) {
            v->obj.capacity *= 2;
            v->obj.entries = realloc(v->obj.entries, sizeof(JsonEntry) * v->obj.capacity);
        }
        v->obj.entries[v->obj.count].key = key;
        v->obj.entries[v->obj.count].val = val;
        v->obj.count++;
        *p = skip_ws(*p);
        if (**p == ',') {
            (*p)++;
            *p = skip_ws(*p);
        } else if (**p == '}') {
            (*p)++;
            break;
        }
    }
    return v;
}

JsonValue *parse_json_array(const char **p) {
    JsonValue *v = create_value(JSON_ARRAY);
    v->arr.capacity = 4;
    v->arr.elements = malloc(sizeof(JsonValue *) * v->arr.capacity);
    v->arr.count = 0;
    (*p)++;
    while (true) {
        *p = skip_ws(*p);
        if (**p == ']') {
            (*p)++;
            break;
        }
        JsonValue *val = parse_json_value(p);
        if (v->arr.count >= v->arr.capacity) {
            v->arr.capacity *= 2;
            v->arr.elements = realloc(v->arr.elements, sizeof(JsonValue *) * v->arr.capacity);
        }
        v->arr.elements[v->arr.count++] = val;
        *p = skip_ws(*p);
        if (**p == ',') {
            (*p)++;
            *p = skip_ws(*p);
        } else if (**p == ']') {
            (*p)++;
            break;
        }
    }
    return v;
}

JsonValue *parse_json_value(const char **p) {
    *p = skip_ws(*p);
    if (**p == '{') return parse_json_object(p);
    if (**p == '[') return parse_json_array(p);
    if (**p == '\"') {
        JsonValue *v = create_value(JSON_STRING);
        v->s = parse_json_string(p);
        return v;
    }
    if (strncmp(*p, "true", 4) == 0) {
        *p += 4;
        JsonValue *v = create_value(JSON_BOOL);
        v->b = true;
        return v;
    }
    if (strncmp(*p, "false", 5) == 0) {
        *p += 5;
        JsonValue *v = create_value(JSON_BOOL);
        v->b = false;
        return v;
    }
    if (strncmp(*p, "null", 4) == 0) {
        *p += 4;
        return create_value(JSON_NULL);
    }
    char *endptr;
    double n = strtod(*p, &endptr);
    *p = endptr;
    JsonValue *v = create_value(JSON_NUMBER);
    v->n = n;
    return v;
}

bool json_equals(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return false;
    switch (a->type) {
        case JSON_NULL: return true;
        case JSON_BOOL: return a->b == b->b;
        case JSON_NUMBER: return a->n == b->n;
        case JSON_STRING: return strcmp(a->s, b->s) == 0;
        case JSON_ARRAY:
            if (a->arr.count != b->arr.count) return false;
            for (int i = 0; i < a->arr.count; i++) if (!json_equals(a->arr.elements[i], b->arr.elements[i])) return false;
            return true;
        case JSON_OBJECT:
            if (a->obj.count != b->obj.count) return false;
            for (int i = 0; i < a->obj.count; i++) {
                bool found = false;
                for (int j = 0; j < b->obj.count; j++) {
                    if (strcmp(a->obj.entries[i].key, b->obj.entries[j].key) == 0) {
                        if (json_equals(a->obj.entries[i].val, b->obj.entries[j].val)) found = true;
                        break;
                    }
                }
                if (!found) return false;
            }
            return true;
    }
    return false;
}

JsonEntry *find_entry(JsonValue *obj, const char *key) {
    for (int i = 0; i < obj->obj.count; i++) {
        if (strcmp(obj->obj.entries[i].key, key) == 0) return &obj->obj.entries[i];
    }
    return NULL;
}

JsonValue *merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *res = create_value(JSON_OBJECT);
        res->obj.capacity = a->obj.count + b->obj.count;
        res->obj.entries = malloc(sizeof(JsonEntry) * res->obj.capacity);
        for (int i = 0; i < a->obj.count; i++) {
            res->obj.entries[res->obj.count].key = my_strdup(a->obj.entries[i].key);
            res->obj.entries[res->obj.count].val = copy_value(a->obj.entries[i].val);
            res->obj.count++;
        }
        for (int i = 0; i < b->obj.count; i++) {
            JsonEntry *existing = find_entry(res, b->obj.entries[i].key);
            if (existing) {
                JsonValue *mv = merge(existing->val, b->obj.entries[i].val);
                free_json_value(existing->val);
                existing->val = mv;
            } else {
                res->obj.entries[res->obj.count].key = my_strdup(b->obj.entries[i].key);
                res->obj.entries[res->obj.count].val = copy_value(b->obj.entries[i].val);
                res->obj.count++;
            }
        }
        return res;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *res = create_value(JSON_ARRAY);
        res->arr.capacity = a->arr.count + b->arr.count;
        res->arr.elements = malloc(sizeof(JsonValue *) * res->arr.capacity);
        for (int i = 0; i < a->arr.count; i++) res->arr.elements[res->arr.count++] = copy_value(a->arr.elements[i]);
        for (int i = 0; i < b->arr.count; i++) {
            bool duplicate = false;
            for (int j = 0; j < res->arr.count; j++) {
                if (json_equals(res->arr.elements[j], b->arr.elements[i])) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) res->arr.elements[res->arr.count++] = copy_value(b->arr.elements[i]);
        }
        return res;
    }
    return copy_value(b);
}

int compare_entries(const void *a, const void *b) {
    return strcmp(((JsonEntry *)a)->key, ((JsonEntry *)b)->key);
}

void sort_value(JsonValue *v) {
    if (v->type == JSON_OBJECT) {
        qsort(v->obj.entries, v->obj.count, sizeof(JsonEntry), compare_entries);
        for (int i = 0; i < v->obj.count; i++) sort_value(v->obj.entries[i].val);
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->arr.count; i++) sort_value(v->arr.elements[i]);
    }
}

void print_indent(int level) {
    for (int i = 0; i < level; i++) printf("  ");
}

void print_json(JsonValue *v, int indent) {
    if (v->type == JSON_NULL) printf("null");
    else if (v->type == JSON_BOOL) printf("%s", v->b ? "true" : "false");
    else if (v->type == JSON_NUMBER) printf("%g", v->n);
    else if (v->type == JSON_STRING) printf("\"%s\"", v->s);
    else if (v->type == JSON_ARRAY) {
        printf("[");
        if (v->arr.count == 0) printf("]");
        else {
            printf("\n");
            for (int i = 0; i < v->arr.count; i++) {
                print_indent(indent + 1);
                print_json(v->arr.elements[i], indent + 1);
                if (i < v->arr.count - 1) printf(",");
                printf("\n");
            }
            print_indent(indent);
            printf("]");
        }
    } else if (v->type == JSON_OBJECT) {
        printf("{");
        if (v->obj.count == 0) printf("}");
        else {
            printf("\n");
            for (int i = 0; i < v->obj.count; i++) {
                print_indent(indent + 1);
                printf("\"%s\": ", v->obj.entries[i].key);
                print_json(v->obj.entries[i].val, indent + 1);
                if (i < v->obj.count - 1) printf(",");
                printf("\n");
            }
            print_indent(indent);
            printf("}");
        }
    }
}

char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    return buf;
}

int main(void) {
    char *str_a = read_file("/tmp/…/config_a.json");
    char *str_b = read_file("/tmp/…/config_b.json");
    if (!str_a || !str_b) return 1;
    const char *p_a = str_a, *p_b = str_b;
    JsonValue *val_a = parse_json_value(&p_a);
    JsonValue *val_b = parse_json_value(&p_b);
    JsonValue *merged = merge(val_a, val_b);
    sort_value(merged);
    print_json(merged, 0);
    printf("\n");
    free_json_value(val_a);
    free_json_value(val_b);
    free_json_value(merged);
    free(str_a);
    free(str_b);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int count;
} LevelNode;

typedef struct {
    char *name;
    int count;
} CompNode;

typedef struct {
    char **msgs;
    int count;
    int cap;
} ErrorList;

int compare_levels(const void *a, const void *b) {
    return strcmp(((LevelNode *)a)->name, ((LevelNode *)b)->name);
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

void add_level(LevelNode **nodes, int *count, int *cap, const char *level) {
    for (int i = 0; i < *count; i++) {
        if (strcmp((*nodes)[i].name, level) == 0) {
            (*nodes)[i].count++;
            return;
        }
    }
    if (*count == *cap) {
        *cap = (*cap == 0) ? 10 : (*cap * 2);
        *nodes = realloc(*nodes, (*cap) * sizeof(LevelNode));
    }
    (*nodes)[*count].name = strdup(level);
    (*nodes)[*count].count = 1;
    (*count)++;
}

void add_comp_error(CompNode **nodes, int *count, int *cap, const char *comp) {
    for (int i = 0; i < *count; i++) {
        if (strcmp((*nodes)[i].name, comp) == 0) {
            (*nodes)[i].count++;
            return;
        }
    }
    if (*count == *cap) {
        *cap = (*cap == 0) ? 10 : (*cap * 2);
        *nodes = realloc(*nodes, (*cap) * sizeof(CompNode));
    }
    (*nodes)[*count].name = strdup(comp);
    (*nodes)[*count].count = 1;
    (*count)++;
}

void add_unique_error(ErrorList *list, const char *msg) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->msgs[i], msg) == 0) return;
    }
    if (list->count == list->cap) {
        list->cap = (list->cap == 0) ? 10 : (list->cap * 2);
        list->msgs = realloc(list->msgs, list->cap * sizeof(char *));
    }
    list->msgs[list->count++] = strdup(msg);
}

int main(void) {
    const char *filepath = "/tmp/…/app.log";
    FILE *fp = fopen(filepath, "r");
    if (!fp) return 0;

    LevelNode *levels = NULL;
    int levels_count = 0, levels_cap = 0;
    CompNode *comps = NULL;
    int comps_count = 0, comps_cap = 0;
    ErrorList errors = {NULL, 0, 0};
    int hour_counts[24] = {0};

    char line[8192];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        char *bracket_open = strchr(p, '[');
        if (!bracket_open) continue;
        char *bracket_close = strchr(bracket_open, ']');
        if (!bracket_close) continue;

        if (strlen(bracket_open) < 14) continue;
        char hour_str[3] = {0};
        hour_str[0] = bracket_open[12];
        hour_str[1] = bracket_open[13];
        int hour = atoi(hour_str);
        if (hour >= 0 && hour < 24) hour_counts[hour]++;

        char *p_level = bracket_close + 1;
        while (*p_level == ' ') p_level++;
        char level[64] = {0};
        int l_idx = 0;
        while (*p_level && *p_level != ' ' && l_idx < 63) level[l_idx++] = *p_level++;
        level[l_idx] = 0;
        add_level(&levels, &levels_count, &levels_cap, level);

        char *p_comp_open = strchr(p_level, '(');
        if (!p_comp_open) continue;
        char *p_comp_close = strchr(p_comp_open, ')');
        if (!p_comp_close) continue;
        char component[128] = {0};
        int c_idx = 0;
        for (char *c = p_comp_open + 1; c < p_comp_close && c_idx < 127; c++) {
            component[c_idx++] = *c;
        }
        component[c_idx] = 0;

        char *p_dash = strchr(p_comp_close, '-');
        if (!p_dash) continue;
        char *message = p_dash + 1;
        while (*message == ' ') message++;
        int msg_len = strlen(message);
        if (msg_len > 0 && message[msg_len - 1] == '\n') message[msg_len - 1] = 0;

        if (strcmp(level, "ERROR") == 0) {
            add_comp_error(&comps, &comps_count, &comps_cap, component);
            add_unique_error(&errors, message);
        }
    }
    fclose(fp);

    qsort(levels, levels_count, sizeof(LevelNode), compare_levels);
    qsort(errors.msgs, errors.count, sizeof(char *), compare_strings);

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < levels_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }

    printf("\n");
    char *max_comp = "None";
    int max_err_count = 0;
    for (int i = 0; i < comps_count; i++) {
        if (comps[i].count > max_err_count) {
            max_err_count = comps[i].count;
            max_comp = comps[i].name;
        }
    }
    printf("Component with Most Errors: %s (%d errors)\n\n", max_comp, max_err_count);

    printf("Unique Error Messages:\n");
    for (int i = 0; i < errors.count; i++) {
        printf("  - %s\n", errors.msgs[i]);
    }

    printf("\n");
    int max_h = 0;
    for (int i = 1; i < 24; i++) {
        if (hour_counts[i] > hour_counts[max_h]) max_h = i;
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", max_h, hour_counts[max_h]);

    for (int i = 0; i < levels_count; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < comps_count; i++) free(comps[i].name);
    free(comps);
    for (int i = 0; i < errors.count; i++) free(errors.msgs[i]);
    free(errors.msgs);

    return 0;
}

use std::fs::File;
use std::io::{self, BufRead};
use std::collections::HashMap;

fn format_currency(n: f64, precision: usize) -> String {
    let s = format!("{:.*}", precision, n);
    let parts: Vec<&str> = s.split('.').collect();
    let int_part = parts[0];
    let mut result = String::new();
    let bytes = int_part.as_bytes();
    let len = bytes.len();
    for i in 0..len {
        if i > 0 && (len - i - 1) % 3 == 0 && bytes[i] != b'-' {
            result.push(',');
        }
        result.push(bytes[i] as char);
    }
    if precision > 0 && parts.len() > 1 {
        result.push('.');
        result.push_str(parts[1]);
    }
    result
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path).expect("Unable to open file");
    let reader = io::BufReader::new(file);

    let mut lines = reader.lines();
    let _header = lines.next();

    let mut dept_sums: HashMap<String, f64> = HashMap::new();
    let mut dept_counts: HashMap<String, usize> = HashMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary = -1.0;
    let mut total_budget = 0.0;

    for line in lines {
        let line = line.expect("Error reading line");
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let cols: Vec<&str> = trimmed.split(',').collect();
        if cols.len() < 4 {
            continue;
        }

        let name = cols[1].trim().to_string();
        let dept = cols[2].trim().to_string();
        let salary: f64 = cols[3].trim().parse().unwrap_or(0.0);

        total_budget += salary;
        *dept_sums.entry(dept.clone()).or_insert(0.0) += salary;
        *dept_counts.entry(dept.clone()).or_insert(0) += 1;

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");

    let mut sorted_depts: Vec<_> = dept_sums.keys().collect();
    sorted_depts.sort();

    for dept in sorted_depts {
        let sum = dept_sums.get(dept).unwrap();
        let count = dept_counts.get(dept).unwrap();
        let avg = sum / (*count as f64);
        println!("  {}: ${}", dept, format_currency(avg, 2));
    }

    println!();
    println!("Highest Paid: {} (${})", highest_paid_name, format_currency(highest_paid_salary, 0));
    println!();
    println!("Departments with >2 employees:");

    let mut sorted_counts_depts: Vec<_> = dept_counts.keys().collect();
    sorted_counts_depts.sort();

    for dept in sorted_counts_depts {
        let count = dept_counts.get(dept).unwrap();
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }

    println!();
    println!("Total Budget: ${}", format_currency(total_budget, 0));
}

