#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

struct Product {
    int id;
    char name[256];
    double price;
    char category[256];
    int stock;
};

int compare_products(const void *a, const void *b) {
    const struct Product *p1 = (const struct Product *)a;
    const struct Product *p2 = (const struct Product *)b;
    return strcmp(p1->name, p2->name);
}

int main(void) {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char *request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    char *response_buffer = malloc(65536);
    if (!response_buffer) return 1;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        free(response_buffer);
        return 1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(18924);
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        close(sock);
        free(response_buffer);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sock);
        free(response_buffer);
        return 1;
    }

    send(sock, request, strlen(request), 0);

    int total_received = 0;
    int n;
    while ((n = recv(sock, response_buffer + total_received, 65536 - total_received - 1, 0)) > 0) {
        total_received += n;
    }
    response_buffer[total_received] = '\0';
    close(sock);

    char *body = strstr(response_buffer, "\r\n\r\n");
    if (body) body += 4;
    else body = response_buffer;

    struct Product *filtered_products = malloc(sizeof(struct Product) * 1000);
    if (!filtered_products) {
        free(response_buffer);
        return 1;
    }

    int count = 0;
    double total_price = 0.0;
    char *ptr = body;

    while ((ptr = strchr(ptr, '{')) != NULL) {
        char *end_obj = strchr(ptr, '}');
        if (!end_obj) break;

        struct Product p;
        memset(&p, 0, sizeof(p));

        char *name_key = strstr(ptr, "\"name\"");
        if (name_key && name_key < end_obj) {
            char *colon = strchr(name_key, ':');
            if (colon && colon < end_obj) {
                char *start_quote = strchr(colon, '\"');
                if (start_quote && start_quote < end_obj) {
                    char *val_start = start_quote + 1;
                    char *val_end = strchr(val_start, '\"');
                    if (val_end && val_end < end_obj) {
                        int len = val_end - val_start;
                        if (len >= 256) len = 255;
                        strncpy(p.name, val_start, len);
                        p.name[len] = '\0';
                    }
                }
            }
        }

        char *price_key = strstr(ptr, "\"price\"");
        if (price_key && price_key < end_obj) {
            char *colon = strchr(price_key, ':');
            if (colon && colon < end_obj) {
                char *val_start = colon + 1;
                while (*val_start == ' ' || *val_start == '\"') val_start++;
                p.price = strtod(val_start, NULL);
            }
        }

        if (p.price > 50.00) {
            filtered_products[count++] = p;
            total_price += p.price;
        }
        ptr = end_obj + 1;
    }

    qsort(filtered_products, count, sizeof(struct Product), compare_products);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < count; i++) {
        printf("%s: $%.2f\n", filtered_products[i].name, filtered_products[i].price);
    }
    printf("\nCount: %d\n", count);
    printf("Total: $%.2f\n", total_price);

    free(response_buffer);
    free(filtered_products);

    return 0;
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    static class FileData {
        String path;
        long lines;
        long bytes;

        FileData(String path, long lines, long bytes) {
            this.path = path;
            this.lines = lines;
            this.bytes = bytes;
        }
    }

    public static void main(String[] args) {
        Path root = Paths.get("/tmp/…/project_tree");
        TreeMap<String, List<FileData>> extensionMap = new TreeMap<>();

        try {
            Files.walk(root).filter(p -> !Files.isDirectory(p)).forEach(p -> {
                try {
                    if (Files.isSymbolicLink(p)) {
                        return;
                    }
                    String filename = p.getFileName().toString();
                    int dotIndex = filename.lastIndexOf('.');
                    String ext = (dotIndex == -1) ? "" : filename.substring(dotIndex);

                    long lines = 0;
                    try (Stream<String> stream = Files.lines(p)) {
                        lines = stream.count();
                    }
                    long bytes = Files.size(p);
                    String relPath = root.relativize(p).toString().replace('\\', '/');

                    extensionMap.computeIfAbsent(ext, k -> new ArrayList<>())
                                .add(new FileData(relPath, lines, bytes));
                } catch (IOException e) {
                    // Ignore files that cannot be read
                }
            });
        } catch (IOException e) {
            // Ignore root access errors
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalBytes = 0;

        for (Map.Entry<String, List<FileData>> entry : extensionMap.entrySet()) {
            String ext = entry.getKey();
            List<FileData> files = entry.getValue();
            Collections.sort(files, Comparator.comparing(f -> f.path));

            long extFiles = files.size();
            long extLines = 0;
            long extBytes = 0;
            for (FileData f : files) {
                extLines += f.lines;
                extBytes += f.bytes;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + extFiles);
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extBytes);
            for (FileData f : files) {
                System.out.println("    " + f.path + ": " + f.lines + " lines, " + f.bytes + " chars");
            }

            totalFiles += extFiles;
            totalLines += extLines;
            totalBytes += extBytes;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalBytes + " characters");
    }
}

