    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut response = String::new();
    stream.read_to_string(&mut response).expect("Failed to read response");

    // Separate header from body
    let body = match response.split("\r\n\r\n").nth(1) {
        Some(b) => b,
        None => "",
    };

    // 2. Parse JSON response (array of objects)
    let mut products = Vec::new();
    let mut current_pos = 0;
    while let Some(start) = body[current_pos..].find('{') {
        let start_abs = current_pos + start;
        if let Some(end_rel) = body[start_abs..].find('}') {
            let end_abs = start_abs + end_rel;
            let object = &body[start_abs..=end_abs];

            // Extract 'name' field
            let name = if let Some(k_idx) = object.find("\"name\"") {
                let after_key = &object[k_idx + 6..];
                if let Some(colon_idx) = after_key.find(':') {
                    let after_colon = &after_key[colon_idx + 1..];
                    if let Some(q1) = after_colon.find('"') {
                        if let Some(q2) = after_colon[q1 + 1..].find('"') {
                            after_colon[q1 + 1..q1 + 1 + q2].to_string()
                        } else { String::new() }
                    } else { String::new() }
                } else { String::new() }
            } else { String::new() };

            // Extract 'price' field
            let price = if let Some(k_idx) = object.find("\"price\"") {
                let after_key = &object[k_idx + 7..];
                if let Some(colon_idx) = after_key.find(':') {
                    let after_colon = &after_key[colon_idx + 1..];
                    let price_str = after_colon.split(',').next().unwrap_or("")
                        .split('}').next().unwrap_or("")
                        .trim();
                    price_str.parse::<f64>().unwrap_or(0.0)
                } else { 0.0 }
            } else { 0.0 };

            products.push(Product { name, price });
            current_pos = end_abs + 1;
        } else {
            break;
        }
    }

    // 3. Filter products where price > 50.00
    let mut filtered: Vec<Product> = products.into_iter().filter(|p| p.price > 50.0).collect();

    // 4. Sort filtered products by name ascending
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    // 5. Print the output in the specified format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total_price = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total_price += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total_price);
}

