function dijkstra() {
    const filePath = '/tmp/…/graph.json';
    const data: GraphData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

    const adj: Map<string, { node: string, weight: number }[]> = new Map();
    for (const node of data.nodes) {
        adj.set(node, []);
    }

    for (const edge of data.edges) {
        adj.get(edge.from)?.push({ node: edge.to, weight: edge.weight });
        adj.get(edge.to)?.push({ node: edge.from, weight: edge.weight });
    }

    const distances: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of data.nodes) {
        distances.set(node, Infinity);
    }

    const startNode = "A";
    if (!distances.has(startNode)) {
        // This case should not happen based on the prompt, but for safety:
        return;
    }
    distances.set(startNode, 0);

    while (visited.size < data.nodes.length) {
        let u: string | null = null;
        let minDistance = Infinity;

        for (const node of data.nodes) {
            if (!visited.has(node)) {
                const d = distances.get(node)!;
                if (d < minDistance) {
                    minDistance = d;
                    u = node;
                }
            }
        }

        if (u === null) break;

        visited.add(u);

        const neighbors = adj.get(u) || [];
        for (const neighbor of neighbors) {
            const alt = distances.get(u)! + neighbor.weight;
            if (alt < (distances.get(neighbor.node) || Infinity)) {
                distances.set(neighbor.node, alt);
            }
        }
    }

    process.stdout.write("=== Shortest Paths from A ===\n\n");
    const sortedNodes = [...data.nodes].sort();
    for (const node of sortedNodes) {
        const dist = distances.get(node);
        process.stdout.write(`A -> ${node}: ${dist}\n`);
    }
}

