use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;
use std::fs;

fn parse_json(content: &str) -> (Vec<String>, Vec<(String, String, u32)>) {
    let mut nodes = Vec::new();
    let mut edges = Vec::new();

    if let Some(nodes_pos) = content.find(r#""nodes""#) {
        if let Some(start_bracket) = content[nodes_pos..].find('[') {
            let start_bracket = start_bracket + nodes_pos;
            if let Some(end_bracket) = content[start_bracket..].find(']') {
                let end_bracket = end_bracket + start_bracket;
                let nodes_part = &content[start_bracket + 1..end_bracket];
                for s in nodes_part.split(',') {
                    let trimmed = s.trim().trim_matches('"');
                    if !trimmed.is_empty() {
                        nodes.push(trimmed.to_string());
                    }
                }
            }
        }
    }

    if let Some(edges_pos) = content.find(r#""edges""#) {
        if let Some(start_bracket) = content[edges_pos..].find('[') {
            let start_bracket = start_bracket + edges_pos;
            if let Some(end_bracket) = content[start_bracket..].find(']') {
                let end_bracket = end_bracket + start_bracket;
                let edges_part = &content[start_bracket + 1..end_bracket];

                let mut current_pos = 0;
                while current_pos < edges_part.len() {
                    if let Some(obj_start) = edges_part[current_pos..].find('{') {
                        let obj_start = obj_start + current_pos;
                        if let Some(obj_end) = edges_part[obj_start..].find('}') {
                            let obj_end = obj_end + obj_start;
                            let obj_trimmed = &edges_part[obj_start + 1..obj_end];

                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0;

                            for pair in obj_trimmed.split(',') {
                                let mut kv = pair.splitn(2, ':');
                                if let (Some(k), Some(v)) = (kv.next(), kv.next()) {
                                    let key = k.trim().trim_matches('"');
                                    let val = v.trim().trim_matches('"');
                                    match key {
                                        "from" => from = val.to_string(),
                                        "to" => to = val.to_string(),
                                        "weight" => weight = val.parse().unwrap_or(0),
                                        _ => {}
                                    }
                                }
                            }
                            edges.push((from, to, weight));
                            current_pos = obj_end + 1;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
            }
        }
    }
    (nodes, edges)
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("Unable to read file");
    let (nodes, edges) = parse_json(&content);

    let mut node_to_idx = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        node_to_idx.insert(node.clone(), i);
    }

    let n = nodes.len();
    let mut adj = vec![Vec::new(); n];
    for (from, to, weight) in edges {
        if let (Some(&u), Some(&v)) = (node_to_idx.get(&from), node_to_idx.get(&to)) {
            adj[u].push((v, weight));
            adj[v].push((u, weight));
        }
    }

    let start_node_name = "A";
    let mut dist = vec![u32::MAX; n];

    if let Some(&start_idx) = node_to_idx.get(start_node_name) {
        dist[start_idx] = 0;
        let mut pq = BinaryHeap::new();
        pq.push(Reverse((0, start_idx)));

        while let Some(Reverse((d, u))) = pq.pop() {
            if d > dist[u] {
                continue;
            }
            for &(v, w) in &adj[u] {
                if dist[u].saturating_add(w) < dist[v] {
                    dist[v] = dist[u] + w;
                    pq.push(Reverse((dist[v], v)));
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();

    for node in sorted_nodes {
        if let Some(&idx) = node_to_idx.get(&node) {
            println!("A -> {}: {}", node, dist[idx]);
        }
    }
}

import Foundation

func isEqual(_ a: Any, _ b: Any) -> Bool {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        if dictA.count != dictB.count { return false }
        for (key, valA) in dictA {
            guard let valB = dictB[key] else { return false }
            if !isEqual(valA, valB) { return false }
        }
        return true
    } else if let arrA = a as? [Any], let arrB = b as? [Any] {
        if arrA.count != arrB.count { return false }
        for (valA, valB) in zip(arrA, arrB) {
            if !isEqual(valA, valB) { return false }
        }
        return true
    } else if let nA = a as? NSNumber, let nB = b as? NSNumber {
        let aIsBool = a is Bool
        let bIsBool = b is Bool
        if aIsBool != bIsBool { return false }
        return nA.isEqual(to: nB)
    } else if let sA = a as? String, let sB = b as? String {
        return sA == sB
    } else if a is NSNull && b is NSNull {
        return true
    }
    return false
}

func deepMerge(a: Any, b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var merged = dictA
        for (key, valueB) in dictB {
            if let valueA = merged[key] {
                merged[key] = deepMerge(a: valueA, b: valueB)
            } else {
                merged[key] = valueB
            }
        }
        return merged
    } else if let arrayA = a as? [Any], let arrayB = b as? [Any] {
        var result = arrayA
        for itemB in arrayB {
            if !result.contains(where: { isEqual($0, itemB) }) {
                result.append(itemB)
            }
        }
        return result
    } else {
        return b
    }
}

func formatJSON(_ value: Any, indent: String = "") -> String {
    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        if sortedKeys.isEmpty { return "{}" }
        var result = "{\n"
        let nextIndent = indent + "  "
        for (index, key) in sortedKeys.enumerated() {
            let val = dict[key]!
            result += "\(nextIndent)\"\(key)\": \(formatJSON(val, indent: nextIndent))"
            if index < sortedKeys.count - 1 {
                result += ","
            }
            result += "\n"
        }
        result += "\(indent)}"
        return result
    } else if let array = value as? [Any] {
        if array.isEmpty { return "[]" }
        var result = "[\n"
        let nextIndent = indent + "  "
        for (index, val) in array.enumerated() {
            result += "\(nextIndent)\(formatJSON(val, indent: nextIndent))"
            if index < array.count - 1 {
                result += ","
            }
            result += "\n"
        }
        result += "\(indent)]"
        return result
    } else {
        if let data = try? JSONSerialization.data(withJSONObject: value, options: []),
           let str = String(data: data, encoding: .utf8) {
            return str
        }
        return "null"
    }
}

