struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn consume_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.consume_whitespace();
        let c = self.peek().expect("Unexpected EOF");
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => JsonValue::String(self.parse_string()),
            't' | 'f' => JsonValue::Boolean(self.parse_boolean()),
            'n' => self.parse_null(),
            '-' | '0'..='9' => JsonValue::Number(self.parse_number()),
            _ => panic!("Unexpected character: {}", c),
        }
    }

    fn parse_string(&mut self) -> String {
        self.advance(); // consume "
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '"' {
                self.advance();
                return s;
            } else if c == '\\' {
                self.advance();
                match self.advance().expect("Unexpected EOF in string") {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\x08'),
                    'f' => s.push('\x0c'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            hex.push(self.advance().expect("Unexpected EOF in unicode escape"));
                        }
                        let code = u32::from_str_radix(&hex, 16).expect("Invalid unicode escape");
                        s.push(std::char::from_u32(code).expect("Invalid unicode char"));
                    }
                    _ => panic!("Invalid escape sequence"),
                }
            } else {
                s.push(self.advance().unwrap());
            }
        }
        panic!("Unterminated string");
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_digit(10) || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
                self.advance();
            } else {
                break;
            }
        }
        self.input[start..self.pos].parse().expect("Invalid number")
    }

    fn parse_boolean(&mut self) -> bool {
        if self.input[self.pos..].starts_with("true") {
            self.pos += 4;
            true
        } else if self.input[self.pos..].starts_with("false") {
            self.pos += 5;
            false
        } else {
            panic!("Expected boolean");
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        if self.input[self.pos..].starts_with("null") {
            self.pos += 4;
            JsonValue::Null
        } else {
            panic!("Expected null");
        }
    }

    fn parse_array(&mut self) -> JsonValue {
        self.advance(); // consume [
        let mut arr = Vec::new();
        self.consume_whitespace();
        if self.peek() == Some(']') {
            self.advance();
            return JsonValue::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.consume_whitespace();
            match self.peek() {
                Some(',') => {
                    self.advance();
                    self.consume_whitespace();
                }
                Some(']') => {
                    self.advance();
                    break;
                }
                _ => panic!("Expected , or ] in array"),
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.advance(); // consume {
        let mut map = BTreeMap::new();
        self.consume_whitespace();
        if self.peek() == Some('}') {
            self.advance();
            return JsonValue::Object(map);
        }
        loop {
            self.consume_whitespace();
            if self.peek() != Some('"') {
                panic!("Expected key in object");
            }
            let key = self.parse_string();
            self.consume_whitespace();
            if self.peek() != Some(':') {
                panic!("Expected : after key in object");
            }
            self.advance();
            map.insert(key, self.parse_value());
            self.consume_whitespace();
            match self.peek() {
                Some(',') => {
                    self.advance();
                    self.consume_whitespace();
                }
                Some('}') => {
                    self.advance();
                    break;
                }
                _ => panic!("Expected , or } in object"),
            }
        }
        JsonValue::Object(map)
    }
}

fn deep_merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut map_a), JsonValue::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.remove(&k) {
                    map_a.insert(k, deep_merge(v_a, v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            JsonValue::Object(map_a)
        }
        (JsonValue::Array(mut arr_a), JsonValue::Array(arr_b)) => {
            for v_b in arr_b {
                if !arr_a.contains(&v_b) {
                    arr_a.push(v_b);
                }
            }
            JsonValue::Array(arr_a)
        }
        (_, b) => b,
    }
}

fn quote(s: &str) -> String {
    let mut res = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => res.push_str("\\\""),
            '\\' => res.push_str("\\\\"),
            '\n' => res.push_str("\\n"),
            '\r' => res.push_str("\\r"),
            '\t' => res.push_str("\\t"),
            _ => res.push(c),
        }
    }
    res.push('"');
    res
}

fn serialize(val: &JsonValue, indent_level: usize) -> String {
    let indent = " ".repeat(indent_level * 2);
    let next_indent = " ".repeat((indent_level + 1) * 2);
    match val {
        JsonValue::String(s) => quote(s),
        JsonValue::Number(n) => {
            if n.fract() == 0.0 {
                format!("{:.0}", n)
            } else {
                n.to_string()
            }
        }
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Array(arr) => {
            if arr.is_empty() { return "[]".to_string(); }
            let mut res = String::from("[\n");
            for (i, v) in arr.iter().enumerate() {
                res.push_str(&format!("{} {}", next_indent, serialize(v, indent_level + 1)));
                if i < arr.len() - 1 { res.push(','); }
                res.push('\n');
            }
            res.push_str(&format!("{}]", indent));
            res
        }
        JsonValue::Object(map) => {
            if map.is_empty() { return "{}".to_string(); }
            let mut res = String::from("{\n");
            let mut first = true;
            for (k, v) in map {
                if !first { res.push_str(",\n"); }
                res.push_str(&format!("{} {}: {}", next_indent, quote(k), serialize(v, indent_level + 1)));
                first = false;
            }
            res.push_str(&format!("\n{}}}", indent));
            res
        }
    }
}

