#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* run_cmd(const char* cmd) {
    FILE* pipe = popen(cmd, "r");
    if (!pipe) return NULL;

    char* result = malloc(1024);
    if (!result) {
        pclose(pipe);
        return NULL;
    }

    if (fgets(result, 1024, pipe) == NULL) {
        result[0] = '\0';
    } else {
        int len = (int)strlen(result);
        while (len > 0 && (result[len - 1] == '\n' || result[len - 1] == '\r' || 
                           result[len - 1] == ' ' || result[len - 1] == '\t')) {
            result[--len] = '\0';
        }
    }

    pclose(pipe);
    return result;
}

int main(void) {
    char* hostname = run_cmd("hostname");
    char* os = run_cmd("uname -s");
    char* architecture = run_cmd("uname -m");
    char* username = run_cmd("whoami");

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname ? hostname : "");
    printf("  \"os\": \"%s\",\n", os ? os : "");
    printf("  \"architecture\": \"%s\",\n", architecture ? architecture : "");
    printf("  \"username\": \"%s\"\n", username ? username : "");
    printf("}\n");

    free(hostname);
    free(os);
    free(architecture);
    free(username);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char *rel_path;
    char *ext;
    long lines;
    long chars;
} FileInfo;

typedef struct {
    FileInfo *files;
    int count;
    int capacity;
} FileList;

void add_file(FileList *list, const char *rel_path, const char *full_path) {
    if (list->count >= list->capacity) {
        list->capacity = (list->capacity == 0) ? 16 : list->capacity * 2;
        list->files = realloc(list->files, list->capacity * sizeof(FileInfo));
    }

    FileInfo *fi = &list->files[list->count];
    fi->rel_path = strdup(rel_path);

    const char *dot = strrchr(rel_path, '.');
    if (dot) {
        fi->ext = strdup(dot);
    } else {
        fi->ext = strdup("");
    }

    fi->lines = 0;
    fi->chars = 0;

    FILE *fp = fopen(full_path, "rb");
    if (fp) {
        char buffer[8192];
        size_t bytes_read;
        while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
            for (size_t i = 0; i < bytes_read; i++) {
                if (buffer[i] == '\n') {
                    fi->lines++;
                }
            }
            fi->chars += bytes_read;
        }
        fclose(fp);
    }
    list->count++;
}

void walk(const char *base, const char *rel, FileList *list) {
    char full_path[4096];
    if (rel == NULL) {
        strncpy(full_path, base, sizeof(full_path));
    } else {
        snprintf(full_path, sizeof(full_path), "%s/%s", base, rel);
    }

    DIR *dir = opendir(full_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char next_rel[4096];
        if (rel == NULL) {
            strncpy(next_rel, entry->d_name, sizeof(next_rel));
        } else {
            snprintf(next_rel, sizeof(next_rel), "%s/%s", rel, entry->d_name);
        }

        char next_full[4096];
        snprintf(next_full, sizeof(next_full), "%s/%s", base, next_rel);

        struct stat st;
        if (stat(next_full, &st) == -1) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(base, next_rel, list);
        } else if (S_ISREG(st.st_mode)) {
            add_file(list, next_rel, next_full);
        }
    }
    closedir(dir);
}

int compare_files(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    int ext_cmp = strcmp(fa->ext, fb->ext);
    if (ext_cmp != 0) return ext_cmp;
    return strcmp(fa->rel_path, fb->rel_path);
}

int main(void) {
    const char *root_path = "/tmp/…/project_tree";
    FileList list = {NULL, 0, 0};

    walk(root_path, NULL, &list);

    qsort(list.files, list.count, sizeof(FileInfo), compare_files);

    printf("=== File Tree Analysis ===\n\n");

    long total_files = 0;
    long total_lines = 0;
    long total_chars = 0;

    for (int i = 0; i < list.count; ) {
        int j = i;
        long group_lines = 0;
        long group_chars = 0;
        while (j < list.count && strcmp(list.files[i].ext, list.files[j].ext) == 0) {
            group_lines += list.files[j].lines;
            group_chars += list.files[j].chars;
            j++;
        }

        printf("Extension: %s\n", list.files[i].ext);
        printf("  Files: %d\n", j - i);
        printf("  Total Lines: %ld\n", group_lines);
        printf("  Total Characters: %ld\n", group_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", list.files[k].rel_path, list.files[k].lines, list.files[k].chars);
        }

        total_files += (j - i);
        total_lines += group_lines;
        total_chars += group_chars;
        i = j;
    }

    printf("\nTotal: %ld files, %ld lines, %ld characters\n", total_files, total_lines, total_chars);

    for (int i = 0; i < list.count; i++) {
        free(list.files[i].rel_path);
        free(list.files[i].ext);
    }
    free(list.files);

    return 0;
}

public class Main {
    public static void main(String[] args) {
        int[][] A = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[][] B = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int[][] C = new int[3][3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }

        int detC = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
                 - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
                 + C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0]);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + detC);
    }

    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            System.out.print("  ");
            for (int i = 0; i < row.length; i++) {
                System.out.printf("%4d", row[i]);
                if (i < row.length - 1) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

