let B = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

var C = Array(repeating: Array(repeating: 0, count: 3), count: 3)
for i in 0..<3 {
    for j in 0..<3 {
        for k in 0..<3 {
            C[i][j] += A[i][k] * B[k][j]
        }
    }
}

func determinant(_ m: [[Int]]) -> Int {
    let a = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
    let b = m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
    let c = m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0])
    return a - b + c
}

func printMatrix(_ matrix: [[Int]]) {
    for row in matrix {
        let rowString = row.map { String(format: "%4d", $0) }.joined(separator: " ")
        print("  " + rowString)
    }
}

