import * as fs from 'fs';
import * as path from 'path';

const ROOT_DIR = '/tmp/…/project_tree';

interface FileStats {
    path: string;
    lines: number;
    chars: number;
}

interface ExtensionGroup {
    totalLines: number;
    totalChars: number;
    files: FileStats[];
}

function walkDirectory(dir: string, root: string, statsMap: Map<string, ExtensionGroup>) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            walkDirectory(fullPath, root, statsMap);
        } else if (entry.isFile()) {
            const content = fs.readFileSync(fullPath);
            const chars = content.length;
            const text = content.toString();
            const lines = text === '' ? 0 : text.split('\n').length;
            const ext = path.extname(entry.name);
            const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

            if (!statsMap.has(ext)) {
                statsMap.set(ext, { totalLines: 0, totalChars: 0, files: [] });
            }

            const group = statsMap.get(ext)!;
            group.totalLines += lines;
            group.totalChars += chars;
            group.files.push({ path: relativePath, lines, chars });
        }
    }
}

function main() {
    const statsMap = new Map<string, ExtensionGroup>();
    walkDirectory(ROOT_DIR, ROOT_DIR, statsMap);

    const sortedExtensions = Array.from(statsMap.keys()).sort();

    process.stdout.write('=== File Tree Analysis ===\n\n');

    let totalFiles = 0;
    let totalLines = 0;
    let totalChars = 0;

    for (const ext of sortedExtensions) {
        const group = statsMap.get(ext)!;
        group.files.sort((a, b) => a.path.localeCompare(b.path));

        process.stdout.write(`Extension: ${ext}\n`);
        process.stdout.write(`  Files: ${group.files.length}\n`);
        process.stdout.write(`  Total Lines: ${group.totalLines}\n`);
        process.stdout.write(`  Total Characters: ${group.totalChars}\n`);

        for (const file of group.files) {
            process.stdout.write(`    ${file.path}: ${file.lines} lines, ${file.chars} chars\n`);
        }

        totalFiles += group.files.length;
        totalLines += group.totalLines;
        totalChars += group.totalChars;
    }

    process.stdout.write(`\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`);
}

