import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.util.regex.*;

public class Main {
    static class Edge {
        String to;
        int weight;

        Edge(String to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class Node implements Comparable<Node> {
        String name;
        long dist;

        Node(String name, long dist) {
            this.name = name;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node other) {
            return Long.compare(this.dist, other.dist);
        }
    }

    public static void main(String[] args) {
        String filePath = "/tmp/…/graph.json";
        try {
            String content = new String(Files.readAllBytes(Paths.get(filePath)));

            // Parse nodes
            int nStart = content.indexOf("\"nodes\"");
            int nOpenBracket = content.indexOf("[", nStart);
            int nCloseBracket = content.indexOf("]", nOpenBracket);
            String nodesPart = content.substring(nOpenBracket + 1, nCloseBracket);
            String[] nodesArray = nodesPart.split(",");
            List<String> nodes = new ArrayList<>();
            for (String n : nodesArray) {
                nodes.add(n.trim().replace("\"", ""));
            }

            // Parse edges
            int eStart = content.indexOf("\"edges\"");
            int eOpenBracket = content.indexOf("[", eStart);
            int eCloseBracket = content.lastIndexOf("]");
            String edgesPart = content.substring(eOpenBracket + 1, eCloseBracket);

            Map<String, List<Edge>> adj = new HashMap<>();
            for (String node : nodes) {
                adj.put(node, new ArrayList<>());
            }

            Pattern p = Pattern.compile("\\{(.*?)\\}");
            Matcher m = p.matcher(edgesPart);
            while (m.find()) {
                String edgeStr = m.group(1);
                String[] pairs = edgeStr.split(",");
                String from = null, to = null;
                int weight = 0;
                for (String pair : pairs) {
                    String[] kv = pair.split(":");
                    if (kv.length < 2) continue;
                    String key = kv[0].trim().replace("\"", "");
                    String val = kv[1].trim().replace("\"", "");
                    if (key.equals("from")) {
                        from = val;
                    } else if (key.equals("to")) {
                        to = val;
                    } else if (key.equals("weight")) {
                        weight = Integer.parseInt(val);
                    }
                }
                if (from != null && to != null) {
                    adj.get(from).add(new Edge(to, weight));
                    adj.get(to).add(new Edge(from, weight));
                }
            }

            // Dijkstra's Algorithm
            Map<String, Long> distances = new HashMap<>();
            for (String node : nodes) {
                distances.put(node, Long.MAX_VALUE);
            }
            distances.put("A", 0L);

            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.add(new Node("A", 0L));

            Set<String> visited = new HashSet<>();

            while (!pq.isEmpty()) {
                Node current = pq.poll();
                String u = current.name;

                if (visited.contains(u)) continue;
                visited.add(u);

                for (Edge edge : adj.getOrDefault(u, new ArrayList<>())) {
                    if (distances.get(u) != Long.MAX_VALUE && distances.get(u) + edge.weight < distances.get(edge.to)) {
                        distances.put(edge.to, distances.get(u) + edge.weight);
                        pq.add(new Node(edge.to, distances.get(edge.to)));
                    }
                }
            }

            // Output
            Collections.sort(nodes);
            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            for (String node : nodes) {
                long dist = distances.get(node);
                System.out.println("A -> " + node + ": " + dist);
            }

        } catch (IOException e) {
            // Silently fail or handle as needed
        }
    }
}

