import Foundation

let rootPath = "/tmp/…/project_tree"
let rootURL = URL(fileURLWithPath: rootPath)
let fileManager = FileManager.default

struct FileStats {
    let path: String
    let lines: Int
    let bytes: Int
}

var extensionMap: [String: [FileStats]] = [:]
var totalFiles = 0
var totalLines = 0
var totalBytes = 0

if let enumerator = fileManager.enumerator(at: rootURL, includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey], options: []) {
    for case let fileURL as URL in enumerator {
        do {
            let resourceValues = try fileURL.resourceValues(forKeys: [.isSymbolicLinkKey, .isRegularFileKey])

            // Do not follow symlinks
            if resourceValues.isSymbolicLink == true {
                continue
            }

            // Only process regular files
            if resourceValues.isRegularFile == true {
                let data = try Data(contentsOf: fileURL)
                let bytes = data.count

                var lines = 0
                for byte in data {
                    if byte == 10 { // '\n'
                        lines += 1
                    }
                }
                // If the file is not empty and does not end with a newline, count the final line
                if !data.isEmpty && data.last != 10 {
                    lines += 1
                }

                let ext = fileURL.pathExtension.isEmpty ? "" : "." + fileURL.pathExtension

                // Calculate relative path
                let relativePath = fileURL.path.replacingOccurrences(of: rootURL.path, with: "")
                var cleanRelativePath = relativePath.hasPrefix("/") ? String(relativePath.dropFirst()) : relativePath

                // Remove 'private/' prefix if it exists to match expected relative path output
                if cleanRelativePath.hasPrefix("private/") {
                    cleanRelativePath = String(cleanRelativePath.dropFirst(8))
                }

                let stats = FileStats(path: cleanRelativePath, lines: lines, bytes: bytes)
                extensionMap[ext, default: []].append(stats)

                totalFiles += 1
                totalLines += lines
                totalBytes += bytes
            }
        } catch {
            continue
        }
    }
}

print("=== File Tree Analysis ===")
print("")

let sortedExtensions = extensionMap.keys.sorted()
for ext in sortedExtensions {
    let files = extensionMap[ext]!.sorted { $0.path < $1.path }
    let extTotalLines = files.reduce(0) { $0 + $1.lines }
    let extTotalBytes = files.reduce(0) { $0 + $1.bytes }

    print("Extension: \(ext)")
    print("  Files: \(files.count)")
    print("  Total Lines: \(extTotalLines)")
    print("  Total Characters: \(extTotalBytes)")
    for file in files {
        print("    \(file.path): \(file.lines) lines, \(file.bytes) chars")
    }
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalBytes) characters")
